CREATE TABLE `annual_goals` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `goal_code` varchar(20) NOT NULL,
  `title` varchar(255) NOT NULL,
  `definition_of_done` text NOT NULL,
  `responsible_department_id` int(11) DEFAULT NULL,
  `annual_target` varchar(255) NOT NULL,
  `priority` enum('HIGH','MEDIUM','LOW') DEFAULT 'MEDIUM',
  `notes` text DEFAULT NULL,
  `status` enum('ACTIVE','INACTIVE','COMPLETED','ARCHIVED') DEFAULT 'ACTIVE',
  `year` varchar(50) NOT NULL,
  `perspective` enum('Financial','Customer','Internal Process','Learning & Growth') DEFAULT NULL,
  `weight` decimal(5,2) DEFAULT 0.00 COMMENT 'Goal weight as a percentage (e.g. 25.00 = 25%)',
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_goal_year` (`goal_code`,`year`),
  KEY `created_by` (`created_by`),
  KEY `idx_ag_year_status` (`year`,`status`),
  KEY `fk_annual_goals_resp_dept_setnull` (`responsible_department_id`),
  CONSTRAINT `annual_goals_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_annual_goals_resp_dept_setnull` FOREIGN KEY (`responsible_department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=59 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
