--
-- Table structure for table `quarterly_submissions`
--

DROP TABLE IF EXISTS `quarterly_submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `quarterly_submissions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `department_id` bigint(20) unsigned NOT NULL,
  `year` varchar(50) NOT NULL,
  `quarter` varchar(10) NOT NULL,
  `months` varchar(255) NOT NULL,
  `total_plans` int(11) NOT NULL DEFAULT 0,
  `done_plans` int(11) NOT NULL DEFAULT 0,
  `not_done_plans` int(11) NOT NULL DEFAULT 0,
  `completion_percentage` decimal(5,2) NOT NULL DEFAULT 0.00,
  `status` varchar(50) NOT NULL DEFAULT 'DRAFT',
  `approval_status` varchar(50) NOT NULL DEFAULT 'PENDING',
  `submission_channel` varchar(50) NOT NULL DEFAULT 'WEB',
  `submitted_by` bigint(20) unsigned DEFAULT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `executive_summary` text DEFAULT NULL,
  `challenges` text DEFAULT NULL,
  `next_quarter_priorities` text DEFAULT NULL,
  `gm_feedback` text DEFAULT NULL,
  `gm_feedback_at` datetime DEFAULT NULL,
  `gm_reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dept_quarterly_period` (`department_id`,`year`,`quarter`),
  KEY `quarterly_submissions_submitted_by_foreign` (`submitted_by`),
  KEY `quarterly_submissions_gm_reviewed_by_foreign` (`gm_reviewed_by`)
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

